/bin/bash -c "node - <<'NODE'
const p=11.5,basic=100e6,opt=10e6,conv=15e6,cash=100e6,oe=120e6;
for (const [name,shares] of [['basic',basic],['fully diluted',basic+opt+conv]]) {
 const eq=p*shares, ev=eq-cash, y=oe/ev;
 console.log(name, {shares, equity_value:eq, enterprise_value:ev, owner_earnings_yield:y, percent:y*100});
}
const fd=basic+opt+conv;
const maxEv=oe/.10;
const maxEq=maxEv+cash;
const maxPrice=maxEq/fd;
console.log('hurdle', {maxEv,maxEq,maxPrice,currentPremium:(p/maxPrice-1)*100,priceDeclineNeeded:(1-maxPrice/p)*100});
NODE
nl -ba investment-policy.md
nl -ba sources/official-filing-2026-q2.json
git status --short"

